// === Tab: mySketch ===
var font;
var vehicles = [];

var formattedTime = "00:00:00";
var prevSec = -1;
var maxChangeForce = 5;

function preload() {
	font = loadFont('https://openprocessing.org/sketch/1307458/files/JosefinSans-Regular.ttf');
}

function setup() {
	createCanvas(windowWidth, windowHeight);
	background(0);

	var points = settingPoints();
	for (var i = 0; i < points.length; i++) {
		var pt = points[i];
		var vehicle = new Vehicle(pt.x, pt.y);
		vehicles.push(vehicle);
	}
}

function draw() {
	background(0);

	calcTime();

	for (var i = 0; i < vehicles.length; i++) {
		var v = vehicles[i];
		v.behaviors();
		v.update();
		v.show();
	}
}

function calcTime() {
	var hours = hour();
	var minutes = minute();
	var seconds = second();

	if(seconds != prevSec) {
		prevSec = seconds;
		hours = nf(hours, 2, 0);
		minutes = nf(minutes, 2, 0);
		seconds = nf(seconds, 2, 0);
		updateText(hours + ":" + minutes + ":" + seconds);
	}
}

function updateText(newText) {
	formattedTime = newText;
	var points = settingPoints();

	if (points.length < vehicles.length) {
		var toSplice = vehicles.length - points.length;
		vehicles.splice(points.length - 1, toSplice);

		applyForce(points);
	} else if (points.length > vehicles.length) {
		for (var i = vehicles.length; i < points.length; i++) {
			var v = vehicles[i - 1].clone();
			vehicles.push(v);
		}

		applyForce(points);
	} else {
		applyForce(points);
	}
}

function settingPoints() {
	var bounds = font.textBounds(formattedTime, 0, 0, 192);
	var posx = width / 2 - bounds.w / 2;
	var posy = height / 2 + bounds.h / 2;

	var points = font.textToPoints(formattedTime, posx, posy, 192, {
		sampleFactor: 0.1
	});
	return points;
}

function applyForce(points) {
	for (var i = 0; i < points.length; i++) {
		vehicles[i].target.x = points[i].x;
		vehicles[i].target.y = points[i].y;
		var force = p5.Vector.random2D();
		force.mult(random(maxChangeForce));
		vehicles[i].applyForce(force);
	}
}

function mousePressed() {
	maxChangeForce += 1;
}

// === Tab: Vehicle ===
function Vehicle(x, y, size) {
	this.pos = createVector(random(width), random(height));
	this.target = createVector(x, y);
	this.vel = p5.Vector.random2D();
	this.acc = createVector();
	if (size != null) {
		this.r = size;
	} else {
		this.r = 8;
	}
	this.maxspeed = 10;
	this.maxforce = 1;
}

Vehicle.prototype.behaviors = function () {
	var arrive = this.arrive(this.target);
	arrive.mult(1);
	this.applyForce(arrive);
}

Vehicle.prototype.applyForce = function (f) {
	this.acc.add(f);
}

Vehicle.prototype.update = function () {
	this.pos.add(this.vel);
	this.vel.add(this.acc);
	this.acc.mult(0);
}

Vehicle.prototype.show = function () {
	stroke(random(255));
	strokeWeight(3);
	line(this.pos.x, 0, this.pos.x, this.pos.y);
}


Vehicle.prototype.arrive = function (target) {
	var desired = p5.Vector.sub(target, this.pos);
	var d = desired.mag();
	var speed = this.maxspeed;
	if (d < 100) {
		speed = map(d, 0, 100, 0, this.maxspeed);
	}
	desired.setMag(speed);
	var steer = p5.Vector.sub(desired, this.vel);
	steer.limit(this.maxforce);
	return steer;
}

Vehicle.prototype.clone = function () {
	var v = new Vehicle(this.pos.x, this.pos.y);

	v.pos.x = this.pos.x;
	v.pos.y = this.pos.y;

	v.vel.x = this.vel.x;
	v.vel.y = this.vel.y;

	v.acc.x = this.acc.x;
	v.acc.y = this.acc.y;

	return v;
}

